// Copies ../glsl/*.glsl into src/shaders.gen.ts (Remotion can't import raw .glsl).
// Runs before studio and render.
import { readFileSync, writeFileSync } from "node:fs";

const pieces = JSON.parse(readFileSync("../src/pieces.json", "utf8"));
const SHADERS = Object.fromEntries(pieces.map((p) => [p.id, { frames: p.frames, frag: readFileSync(`../glsl/${p.id}.glsl`, "utf8") }]));

writeFileSync("src/shaders.gen.ts",
  "// GENERATED by gen-shaders.mjs — edit ../src/*.glsl instead\n" +
  "export const SHADERS: Record<string, { frames: number; frag: string }> = " + JSON.stringify(SHADERS, null, 1) + ";\n");
console.log("src/shaders.gen.ts ready");
